  const c = state.context;
  return m05Gateway(state, 'report', {
    run_id: state.runId,
    account_id: c.account.account_id,
    status: c.status === 'success' ? 'success' : 'failed',
    items_seen: c.items.length,
    items_new: c.inserted,
    error: c.error,
